    // About page
    aboutHeroTagline: "Réinventer la façon de vivre Israël",
    aboutWhyIsraelLabel: "POURQUOI ISRAËL. POURQUOI MAINTENANT.",
    aboutWhyIsraelTitle: "Une nouvelle façon de vivre Israël",
    aboutWhyIsraelP1: "Un pays aussi riche mérite mieux que des listes d'hôtels génériques et des packages préfabriqués.",
    aboutWhyIsraelP2: "Israël est l'une des destinations les plus diverses, les plus riches culturellement et les plus chargées d'émotions au monde. Et pourtant, la façon dont on la découvre et réserve n'a pas évolué.",
    aboutWhyIsraelP3: "STAYMAKOM est né pour changer ça : apporter de l'intention, de la sélection et quelque chose à raconter dans chaque séjour en Israël.",
    aboutAudienceIsraeliTitle: "Voyageurs israéliens",
    aboutAudienceIsraeliP1: "Vous connaissez déjà le pays, mais pas comme ça.",
    aboutAudienceIsraeliP2: "STAYMAKOM aide les Israéliens à redécouvrir leur propre terre à travers des séjours d'exception qui ressemblent à une vraie évasion, pas juste un autre week-end. Retraites en semaine, escapades romantiques, aventures en famille, tout pensé avec intention.",
    aboutAudienceIntlTitle: "Visiteurs internationaux",
    aboutAudienceIntlP1: "Israël au-delà du guide touristique.",
    aboutAudienceIntlP2: "Pour les voyageurs venus de l'étranger, STAYMAKOM ouvre une face d'Israël que la plupart ne voient jamais : hôtels boutiques dans le désert, parcours culinaires en Galilée, retraites bien-être près de la mer Morte, le tout réservable en une seule expérience fluide.",
    aboutDifferentTitle: "Ce qui rend STAYMAKOM unique",
    aboutDifferent1: "Des hôtels sélectionnés, pas simplement listés",
    aboutDifferent2: "Des expériences incluses, pas des options supplémentaires",
    aboutDifferent3: "Chaque séjour est conçu autour d'un lieu, pas d'une chambre",
    aboutDifferent4: "Pas de scroll interminable, seulement des choix pertinents",
    aboutDifferent5: "Une plateforme, une réservation, un séjour cohérent",
    aboutDifferentQuote: "STAYMAKOM ne cherche pas à tout offrir. Il existe pour proposer les bons séjours, aux bonnes personnes, au bon moment.",
    aboutNameTitle: "Pourquoi ce nom",
    aboutNameP1: "Makom signifie « lieu » en hébreu. Pas seulement un endroit, mais un lieu qui a une présence et une signification.",
    aboutNameP2: "STAYMAKOM, c'est séjourner quelque part qui vous correspond vraiment. Un endroit qui laisse une trace. Un endroit dont on se souvient longtemps après l'avoir quitté.",
    aboutFounderLabel: "LA FONDATRICE",
    aboutFounderName: "SHANA",
    aboutFounderRole: "Fondatrice & CEO",
    aboutFounderP1: "J'ai passé sept ans à développer et structurer une marque hôtelière en France. Mais Israël a toujours fait partie de ma vie. J'y venais chaque année depuis toute petite (surtout à Tel Aviv et Jérusalem), et pourtant j'avais toujours le sentiment de n'effleurer que la surface.",
    aboutFounderP2: "Les endroits les plus significatifs n'étaient pas évidents à trouver. Les séjours les plus uniques étaient difficiles à dénicher. Tout semblait fragmenté.",
    aboutFounderP3: "Alors j'ai construit ce que je ne trouvais pas.",
    aboutFounderP4: "STAYMAKOM est né de quelque chose de personnel : une façon de vivre Israël au-delà du familier, en réunissant des hôtels d'exception et des expériences soigneusement sélectionnées dans un seul voyage fluide. Parce que dans un pays aussi riche en couches, l'endroit où vous séjournez doit faire partie de l'histoire.",
