export type Language = 'en' | 'he' | 'fr';
export type UiKey = keyof typeof translations.en;
export type UiDictionary = Partial<typeof translations.en>;

/** Dictionnaire d'une langue : écrit à la main (en, he, fr) ou traduit (es, ru, de). */
function dictionaryOf(locale: Locale): UiDictionary {
  if (locale === "en" || locale === "he" || locale === "fr") return translations[locale] as UiDictionary;
  return AUTO_UI_TRANSLATIONS[locale] ?? {};
}

/** Texte d'interface dans la langue de la page, l'anglais si la clé n'est pas encore traduite. */
export const t = (lang: Locale, key: UiKey): any => dictionaryOf(lang)[key] ?? translations.en[key];

/**
 * Langue réelle de la page en cours (en, fr, he, es, ru, de). Les espaces équipe (back-office,
 * hôtels, prestataires) ne passent jamais en espagnol / russe / allemand : anglais à la place.
 */
export const pageLocale = (): Locale => {
  if (typeof window === "undefined") return "en";
  const locale = resolveLocale();
  return isAutoLocale(locale) && /^\/(admin|hotel-admin|partner)(\/|$)/.test(window.location.pathname) ? "en" : locale;
};

/**
 * Texte d'interface dans la langue de la page en cours (même règle que useLanguage : ?lang= de
 * l'adresse, sinon dernier choix mémorisé, sinon langue de l'appareil). Sert aux composants dont
 * les textes ont été rapatriés automatiquement : ils sont déjà redessinés à chaque changement de
 * langue (ils utilisent useLanguage), la langue lue ici est donc toujours celle affichée.
 */
export const tPage = (key: UiKey): any => t(pageLocale(), key);

/**
 * Un petit dictionnaire de composant (ex. les textes de la page de paiement), dans la langue de
 * la page : toutes les clés « prefixe__nom » renvoyées sous la forme { nom: texte }.
 */
export const uiGroup = (prefix: string): any => {
  const head = `${prefix}__`;
  const group: Record<string, unknown> = {};
  for (const key of Object.keys(translations.en) as UiKey[]) {
    if (!key.startsWith(head)) continue;
    // « titres.favoris.titre » → { titres: { favoris: { titre } } }
    const path = key.slice(head.length).split(".");
    let node = group;
    for (const part of path.slice(0, -1)) node = (node[part] ??= {}) as Record<string, unknown>;
    node[path[path.length - 1]] = tPage(key);
  }
  return group;
};

/**
 * Un texte dans toutes les langues du site, { en, fr, he, es, ru, de } (une langue non traduite
 * reçoit l'anglais). Remplace les petites fiches { en, fr, he } des listes (pays, options...),
 * lues ensuite avec la langue de la page : uiRecord("clé")[pageLocale()].
 */
export const uiRecord = (key: UiKey): Record<Locale, string> =>
  Object.fromEntries(ALL_LOCALES.map((locale) => [locale, t(locale, key)])) as Record<Locale, string>;


/** Clés anglaises encore absentes d'une langue (sert à la check-list avant d'allumer ES / RU / DE). */
export const missingUiKeys = (locale: Locale): UiKey[] =>
  (Object.keys(translations.en) as UiKey[]).filter((key) => !(key in dictionaryOf(locale)));
